function initHinchada(){
  /* Las ramas ya no se listan a mano aquí: la tabla RAMAS dice cuáles existen y
     initRamas() se encarga de la ficha de cada una. Un mapa vacío vale porque
     todo lo que las lee pregunta por rs[k], y undefined es tan falso como false. */
  G.hincha=G.hincha||{abono:'general',abonados:0,precioDin:false,peñas:[],
    ramas:{},
    seg:{historicos:60,nuevos:55,barra:55,familias:60,socios:60},
    encuesta:null,diaHincha:0};
  return G.hincha;
}

