/* ============================================================
   RAMAS DEPORTIVAS DEL CLUB
   Antes eran tres booleanos y lo único que los leía era el cobro del
   mantenimiento: abrir una rama era pagar por una etiqueta que no volvía a
   pasar nada. Ahora cada rama es una sección viva —nivel de inversión, apoyo
   interno, temporada propia, palmarés y riesgo real de abandono— y lo que
   devuelve al club se cobra en sitios que YA existían: la subvención
   municipal, las ofertas de las marcas, los vecinos, la cantera, la funa,
   los lesionados y los seguidores.
   [id, icono, nombre, apertura, mantenimiento semanal, prestigio base, perfil, descripción] */
const RAMAS=[
  ['femenino','⚽','Fútbol femenino',1400000,22000,7,'cantera','Rama competitiva completa: reputación social y una cantera nueva'],
  ['futsal','🥅','Futsal',420000,6000,3,'barrio','Barato y muy querido por el barrio'],
  ['adaptado','♿','Deporte adaptado',380000,5000,6,'imagen','Impacto institucional enorme y sponsors que solo firman con clubes inclusivos'],
  ['basquet','🏀','Baloncesto',900000,15000,5,'taquilla','Llena el polideportivo entre semana con su propia taquilla'],
  ['voley','🏐','Vóleibol',520000,8000,3,'barrio','Deporte de colegio: la rama que más acerca a las familias del barrio'],
  ['balonmano','🤾','Balonmano',560000,9000,3,'taquilla','Sección modesta y fiel, con su liga y su gente de siempre'],
  ['atletismo','🏃','Atletismo',600000,9000,4,'fisico','Pista, gimnasio y preparadores compartidos con el primer equipo'],
  ['natacion','🏊','Natación',700000,11000,4,'fisico','Piscina propia: recuperación sin impacto para los lesionados'],
  ['ciclismo','🚴','Ciclismo',760000,12000,4,'marca','El maillot del club recorre el país entero delante de las cámaras'],
  ['esports','🎮','eSports',480000,7000,3,'digital','Compite online y arrastra a un público que no pisa el estadio'],
  ['playa','🏖️','Fútbol playa',300000,4000,2,'marca','Torneos de verano en la costa: el club sale en las noticias en enero'],
  ['ajedrez','♟️','Ajedrez',120000,1500,2,'imagen','Barato, silencioso, y deja al club como una institución seria']
];
/* Nivel de inversión: [id, nombre, ×coste, deriva semanal del apoyo, bonus de fuerza].
   «Mínimos» es la trampa: ahorra hoy y va vaciando la rama hasta el abandono. */
const RAMA_NIV=[
  ['minimos','Mínimos',0.5,-3,-7],
  ['normal','Normal',1.0,0,0],
  ['profesional','Profesional',2.0,1,8]
];
/* Qué devuelve cada perfil. Tabla y no ifs sueltos: cada entrada trae la etiqueta
   que se PINTA y, al lado, la función que se EJECUTA de verdad cada semana.
   Todo lo que tocan (funa, vecinos, lesiones, seguidores, moral, caja) ya tenía
   lectores en el juego: por eso se nota jugando y no solo en el menú. */
const RAMA_PERFIL={
  cantera :['🎓 Cantera','Forma gente de la casa: cada temporada sube un juvenil al club',
    (d,r)=>{for(const j of plantelDe(G.miClub))if(j.edad<=20)j.moral=clamp(j.moral+1,10,99);}],
  barrio  :['🏘️ Barrio','Acerca a los vecinos: sube la relación con la ciudad y la subvención',
    (d,r)=>{const C=initCiudad();C.vecinos=clamp(C.vecinos+1,0,100);}],
  imagen  :['🏛️ Imagen','Institución respetada: apaga el ruido de fuera y pesa en las marcas',
    (d,r)=>{if((G.funa||0)>0)G.funa=Math.max(0,G.funa-1);}],
  taquilla:['🎟️ Taquilla','Vende sus propias entradas cada fin de semana',
    (d,r)=>{mov(esc$(R(1500,4800)),'Taquilla de '+d[2]);}],
  fisico  :['💪 Físico','Gimnasio, pista y fisios compartidos: los lesionados vuelven antes',
    (d,r)=>{const les=plantelDe(G.miClub).filter(j=>j.lesion>0);if(!les.length)return;const j=pick(les);j.lesion=Math.max(0,j.lesion-1);}],
  marca   :['📣 Marca','El escudo aparece donde el fútbol no llega',
    (d,r)=>{G.social=G.social||{posts:[],seg:1200,trend:[]};G.social.seg=Math.round(G.social.seg*1.005)+R(10,60);}],
  digital :['💻 Digital','Trae seguidores jóvenes que no pisan el estadio',
    (d,r)=>{G.social=G.social||{posts:[],seg:1200,trend:[]};G.social.seg=Math.round(G.social.seg*1.009)+R(20,90);G.socios+=R(5,30);}]
};
function fichaRama(){
  return {niv:1,apoyo:R(58,72),pj:0,pg:0,pe:0,pp:0,titulos:0,ult:'',año:G.año,impagos:0,desde:G.año};
}
/* La ficha se normaliza AQUÍ y no en migrar(): migrar() solo corre al CARGAR, así
   que en partida nueva la rama nacería sin ficha y todo lo que la lee (temporada,
   apoyo, impagos) daría undefined. Las partidas viejas guardaban la rama como un
   simple `true`: aquí se convierte en ficha completa. */
function initRamas(){
  const H=initHinchada();
  H.ramas=H.ramas||{};
  const base=fichaRama();                 // una sola plantilla para rellenar huecos
  for(const d of RAMAS){
    const k=d[0],v=H.ramas[k];
    if(!v)continue;
    if(v===true){H.ramas[k]=fichaRama();continue;}
    for(const c in base)if(v[c]==null)v[c]=base[c];
  }
  return H.ramas;
}
/* Prestigio que las ramas devuelven al club. Es un número CON LECTORES REALES:
   entra en subvencionAnual() y en generarSponsorOfertas(). Sin ellos esto sería
   otra etiqueta bonita, que es justo lo que el proyecto no permite. */
function prestigioRamas(){
  const rs=initRamas();
  let p=0;
  for(const d of RAMAS){
    const r=rs[d[0]];if(!r)continue;
    p+=d[5]*(0.45+r.apoyo/160)*(1+Math.min(r.titulos,6)*0.14);
  }
  return Math.round(clamp(p,0,60));
}
function costeRamas(){
  const rs=initRamas();
  let s=0;
  for(const d of RAMAS){
    const r=rs[d[0]];if(!r)continue;
    s+=Math.max(1,Math.round(esc$(d[4])*(RAMA_NIV[r.niv]||RAMA_NIV[1])[2]));
  }
  return s;
}
function abrirRama(k){
  const rs=initRamas();
  const d=RAMAS.find(x=>x[0]===k);if(!d)return;
  if(rs[k]){toast("Ya existe esa rama");return;}
  const c=esc$(d[3]);
  if(G.saldo<c){toast("Cuesta "+fmt$(c));return;}
  mov(-c,"Creación de la rama: "+d[2]);
  rs[k]=fichaRama();
  /* Abrir una rama regalaba +3 de reputación. Con doce ramas eso serían +36 gratis:
     ahora el prestigio vuelve por prestigioRamas() y por los títulos que gane. */
  G.dt.rep=clamp(G.dt.rep+1,1,99);
  G.animo=clamp((G.animo||60)+R(4,9),0,100);
  G.socios+=R(300,1400);
  initCiudad().vecinos=clamp(initCiudad().vecinos+R(2,5),0,100);
  noticia(d[1]+" Nace la rama de "+d[2],
    d[7]+". Mantenerla cuesta "+fmt$(esc$(d[4]))+" a la semana. Si la dejas sin dinero se vacía, "+
    "y una rama vacía acaba abandonando el club con todo el escándalo que eso trae.");
  post('El club abre su rama de '+d[2]+'. Ya era hora.','hincha',2.0);
  render();
}
function invertirRama(k,paso){
  const rs=initRamas();const r=rs[k];if(!r)return;
  const d=RAMAS.find(x=>x[0]===k);if(!d)return;
  const nv=clamp(r.niv+paso,0,RAMA_NIV.length-1);
  if(nv===r.niv)return;
  if(nv>r.niv){
    const c=Math.round(esc$(d[3])*0.35);
    if(G.saldo<c){toast("Ampliar la rama cuesta "+fmt$(c));return;}
    mov(-c,"Ampliación de la rama: "+d[2]);
    r.apoyo=clamp(r.apoyo+R(6,14),0,100);
    noticia(d[1]+" La rama de "+d[2]+" pasa a «"+RAMA_NIV[nv][1]+"»",
      "Más horas, mejor cuerpo técnico y fichas para las figuras: la sección compite de otra manera. El mantenimiento sube a "+
      fmt$(Math.round(esc$(d[4])*RAMA_NIV[nv][2]))+" a la semana.");
  }else{
    r.apoyo=clamp(r.apoyo-R(8,16),0,100);
    noticia(d[1]+" Recortes en la rama de "+d[2],
      "La sección baja a «"+RAMA_NIV[nv][1]+"». Se ahorra dinero, pero dentro lo leen como un abandono en cámara lenta y el apoyo se desploma.");
    post('Recortan en la rama de '+d[2]+'. Así se matan las secciones.','hincha',1.6);
  }
  r.niv=nv;
  render();
}
function cerrarRama(k){
  const rs=initRamas();const r=rs[k];if(!r)return;
  const d=RAMAS.find(x=>x[0]===k);if(!d)return;
  /* Doble pulsación, como en retirarse(): cerrar una sección no se deshace. */
  if(vista.confCerrar!==k){vista.confCerrar=k;toast("Pulsa otra vez para cerrar la rama: no hay vuelta atrás");render();return;}
  vista.confCerrar=null;
  const ahorro=Math.round(esc$(d[4])*(RAMA_NIV[r.niv]||RAMA_NIV[1])[2]);
  delete rs[k];
  G.animo=clamp((G.animo||60)-R(6,14),0,100);
  G.socios=Math.max(0,G.socios-R(300,1500));
  G.dt.rep=clamp(G.dt.rep-2,1,99);
  initCiudad().vecinos=clamp(initCiudad().vecinos-R(4,10),0,100);
  const H=initHinchada();
  H.seg.historicos=clamp(H.seg.historicos-R(6,14),0,100);
  noticia("🔒 El club cierra la rama de "+d[2],
    "Decisión de despacho: se disuelve la sección tras "+Math.max(0,G.año-r.desde)+" temporada(s) y "+r.titulos+" título(s). "+
    "Te ahorras "+fmt$(ahorro)+" a la semana y te llevas la cara de los socios históricos.");
  post('Cierran la rama de '+d[2]+'. Un club es más que once tipos.','hincha',2.4);
  render();
}
/* La rama se harta y se va sola. Esto es lo que le faltaba al sistema: que el
   descuido tenga precio y no solo la chequera. */
function abandonoRama(k,d,r){
  const rs=initRamas();
  delete rs[k];
  G.animo=clamp((G.animo||60)-R(8,16),0,100);
  G.socios=Math.max(0,G.socios-R(400,2000));
  G.dt.rep=clamp(G.dt.rep-R(2,4),1,99);
  G.funa=(G.funa||0)+R(6,14);
  initCiudad().vecinos=clamp(initCiudad().vecinos-R(5,12),0,100);
  const H=initHinchada();
  H.seg.historicos=clamp(H.seg.historicos-R(8,16),0,100);
  H.seg.socios=clamp(H.seg.socios-R(6,14),0,100);
  noticia("💔 "+d[1]+" La rama de "+d[2]+" abandona el club",
    "Tras "+Math.max(0,G.año-r.desde)+" temporada(s) y "+r.titulos+" título(s), la sección se marcha en bloque: renuncia el cuerpo técnico y la plantilla ficha por el club de al lado. "+
    "Llevaban semanas con el apoyo por los suelos"+(r.impagos?" y "+r.impagos+" semana(s) sin cobrar":"")+", y nadie del primer equipo fue a despedirlos.");
  post('Se va la rama de '+d[2]+'. Vergüenza de dirigencia.','barra',2.8);
}
/* Cada rama tiene su propio año deportivo: se cierra cuando cambia el del club. */
function cerrarTemporadaRama(k,d,r){
  const rend=r.pj?(r.pg*3+r.pe)/(r.pj*3):0;
  if(r.pj>=8&&rend>=0.66){
    r.titulos++;
    const premio=esc$(40000+d[5]*9000);
    mov(premio,"Título de la rama · "+d[2]);
    G.dt.rep=clamp(G.dt.rep+1,1,99);
    G.animo=clamp((G.animo||60)+R(3,7),0,100);
    G.socios+=R(200,900);
    r.apoyo=clamp(r.apoyo+R(6,12),0,100);
    noticia("🏆 "+d[1]+" ¡Campeón la rama de "+d[2]+"!",
      "La sección cierra su liga con "+r.pg+"-"+r.pe+"-"+r.pp+" y se lleva el título. Entran "+fmt$(premio)+" en premios y el club entero se cuelga la medalla. Van "+r.titulos+" título(s) de esta rama.");
    post('¡Campeones en '+d[2]+'! El club es mucho más que el primer equipo.','hincha',2.5);
    sfx('trofeo');
  }else if(r.pj>=8&&rend<0.28){
    r.apoyo=clamp(r.apoyo-R(8,16),0,100);
    noticia(d[1]+" Año para olvidar en "+d[2],
      "La rama termina "+r.pg+"-"+r.pe+"-"+r.pp+" y baja de categoría. La gente de la sección mira al despacho y pregunta si a alguien le importa.");
  }
  /* Las ramas formativas suben gente DE VERDAD, no una etiqueta: el juvenil
     aparece en Plantel → Juveniles y se puede entrenar, hacer debutar o vender. */
  if(d[6]==='cantera'&&r.apoyo>=40){
    const c=G.clubes[G.miClub];
    const j=nuevoJugador(G.miClub,pick(['POR','DEF','DEF','MED','MED','DEL']),R(16,18),(c?c.rep:70)-20+R(0,7)+r.niv*2);
    j.pot=clamp(j.ovr+R(10,26),j.ovr,97);
    j.canterano=true;j.desde=G.año;j.ramaOrigen=d[2];
    G.jug[j.id]=j;
    noticia("🎓 "+d[1]+" Sube al primer club desde "+d[2],
      j.nombre+" ("+j.posE+", "+j.edad+" años, proyección "+j.pot+") se formó en la rama y pasa a la cantera. Lo tienes en Plantel → Juveniles.");
  }
  r.pj=0;r.pg=0;r.pe=0;r.pp=0;r.ult='';r.año=G.año;
}
/* Motor semanal de las ramas: sustituye a los tres cobros escritos a mano. */
function procesoRamas(){
  const rs=initRamas();
  for(const d of RAMAS){
    const k=d[0],r=rs[k];
    if(!r)continue;
    if(r.año!==G.año){cerrarTemporadaRama(k,d,r);continue;}
    const nv=RAMA_NIV[r.niv]||RAMA_NIV[1];
    // 1. mantenimiento sacado de la TABLA, no de un if por rama
    const costo=Math.max(1,Math.round(esc$(d[4])*nv[2]));
    if(G.saldo<costo){
      r.impagos++;
      r.apoyo=clamp(r.apoyo-R(5,12),0,100);
      if(r.impagos===2)noticia("⚠️ "+d[1]+" La rama de "+d[2]+" lleva dos semanas sin cobrar",
        "Entrenadores y deportistas de la sección no ven un euro. Si esto sigue, se van y la rama desaparece del club.");
    }else{mov(-costo,"Mantenimiento · "+d[2]);r.impagos=0;}
    // 2. su propia competición, jornada a jornada
    if(G.sem>=2&&G.sem<=30){
      const rep=(G.clubes[G.miClub]||{}).rep||70;
      const fuerza=48+nv[4]+(r.apoyo-60)*0.35+(rep-70)*0.35-r.impagos*4;
      const pG=clamp(0.20+(fuerza-48)*0.011,0.06,0.72);
      const x=RF();
      r.pj++;
      if(x<pG){r.pg++;r.ult='ganó';r.apoyo=clamp(r.apoyo+1,0,100);}
      else if(x<pG+0.24){r.pe++;r.ult='empató';}
      else{r.pp++;r.ult='perdió';r.apoyo=clamp(r.apoyo-1,0,100);}
    }
    // 3. deriva del apoyo: el nivel de inversión y el ánimo del club tiran de él
    r.apoyo=clamp(r.apoyo+nv[3]*(RF()<0.5?1:0)+((G.animo||60)>65?1:-1)*(RF()<0.25?1:0),0,100);
    // 4. lo que devuelve al club, según su perfil
    const P=RAMA_PERFIL[d[6]];
    if(P&&r.apoyo>=30&&RF()<0.35+r.niv*0.15)P[2](d,r);
    // 5. abandono: una rama vaciada se va, y se nota en toda la partida
    if(r.apoyo<=16&&RF()<0.08+r.impagos*0.04)abandonoRama(k,d,r);
  }
}

